export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const tTop = launchSpeed / gravity;
  const yTop = (launchSpeed * launchSpeed) / (2 * gravity);

  const tossedVelocity = launchSpeed - gravity * time;
  const tossedAcceleration = -gravity;
  const tossedHeight = launchSpeed * time - 0.5 * gravity * time * time;

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = yTop;
  const isReleased = time >= tTop;
  if (isReleased) {
    const dt = time - tTop;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = yTop - 0.5 * gravity * dt * dt;
  }

  const frameW = 640;
  const frameH = 420;
  const laneW = 280;
  const laneH = 360;
  const tossX = 20;
  const dropX = 340;
  const laneY = 30;

  let tossState = "At launch";
  if (Math.abs(time - tTop) < 0.02) {
    tossState = "At the top";
  } else if (time < tTop) {
    tossState = "Rising";
  } else if (tossedHeight <= 0.02) {
    tossState = "At launch height";
  } else {
    tossState = "Falling";
  }

  let dropState = "Held in place";
  if (isReleased) {
    if (Math.abs(time - tTop) < 0.02) {
      dropState = "Just released";
    } else if (dropHeight <= 0.02) {
      dropState = "At launch height";
    } else {
      dropState = "Falling together";
    }
  }

  const tossPanel = sdk.panel({ x: tossX, y: laneY, w: laneW, h: laneH, title: "Toss Lane", state: tossState, id: "lane.toss" });
  const dropPanel = sdk.panel({ x: dropX, y: laneY, w: laneW, h: laneH, title: "Drop Lane", state: dropState, id: "lane.drop" });

  const axisY = laneY + 50;
  const axisH = 260;
  const minY = 0;
  const maxY = 2.2;

  const tossAxis = sdk.axis("axis.toss", { x: tossX + 65, y: axisY + axisH, length: axisH, orientation: "y", min: minY, max: maxY, label: "Height", unit: "m" });
  const dropAxis = sdk.axis("axis.drop", { x: dropX + 65, y: axisY + axisH, length: axisH, orientation: "y", min: minY, max: maxY, label: "Height", unit: "m" });

  const heightToPixel = (h) => axisY + axisH - (sdk.clamp(h, 0, maxY) / maxY) * axisH;

  const tossBallY = heightToPixel(tossedHeight);
  const dropBallY = heightToPixel(dropHeight);
  const gateY = heightToPixel(yTop);
  const tossBallX = tossX + 160;
  const dropBallX = dropX + 160;

  const tossBall = sdk.circle("ball.toss", tossBallX, tossBallY, 24);
  const dropBall = sdk.circle("ball.drop", dropBallX, dropBallY, 24);
  const gate = sdk.gate("gate", dropBallX, gateY, { open: isReleased, label: "Apex Gate" });

  const vScale = 15;
  const aScale = 6;

  const vecVToss = sdk.vector("vec.v.toss", { x: tossBallX - 25, y: tossBallY }, { value: tossedVelocity, direction: "up", scale: vScale, label: "v" });
  const vecVDrop = sdk.vector("vec.v.drop", { x: dropBallX - 25, y: dropBallY }, { value: dropVelocity, direction: "up", scale: vScale, label: "v" });

  const vecAToss = sdk.vector("vec.a.toss", { x: tossBallX + 25, y: tossBallY }, { value: tossedAcceleration, direction: "up", scale: aScale, label: "a" });
  const vecADrop = sdk.vector("vec.a.drop", { x: dropBallX + 25, y: dropBallY }, { value: dropAcceleration, direction: "up", scale: aScale, label: "a" });

  const calloutToss = sdk.callout(tossBallX + 35, tossBallY - 20, [`v: ${sdk.format(tossedVelocity, 2)} m/s`, `a: ${sdk.format(tossedAcceleration, 2)} m/s²`], { id: "callout.toss" });
  const calloutDrop = sdk.callout(dropBallX + 35, dropBallY - 20, [`v: ${sdk.format(dropVelocity, 2)} m/s`, `a: ${sdk.format(dropAcceleration, 2)} m/s²`], { id: "callout.drop" });

  const objects = [
    ...tossPanel,
    ...dropPanel,
    tossAxis,
    dropAxis,
    ...gate,
    tossBall,
    dropBall,
    ...vecVToss,
    ...vecVDrop,
    ...vecAToss,
    ...vecADrop,
    ...calloutToss,
    ...calloutDrop
  ];

  const readouts = [
    { id: "tossedVelocity", value: tossedVelocity },
    { id: "tossedAcceleration", value: tossedAcceleration },
    { id: "dropVelocity", value: dropVelocity },
    { id: "dropAcceleration", value: dropAcceleration }
  ];

  const quantities = {
    launchSpeed,
    gravity,
    apexTime: tTop,
    apexHeight: yTop,
    tossedVelocity,
    tossedAcceleration,
    tossedHeight,
    dropVelocity,
    dropAcceleration,
    dropHeight
  };

  return {
    frame: sdk.frame(objects, { width: frameW, height: frameH, readouts }),
    quantities
  };
}
